import sys
sys.path.insert(0,'/app/work')
from prep import *
from scipy.optimize import minimize_scalar
pd.set_option('display.width',250); pd.set_option('display.max_columns',50); pd.set_option('display.max_rows',800)

df0=pd.read_pickle('/app/work/df2.pkl')
df0=df0[~df0.decoy].copy()
ACT={'TURBINE':1612,'COOLING':1655,'STEAM_GEN':1748,'PRIMARY_LOOP':1932,'CORE':2396}
sig={sid:g[g.tmin<1440+20].dev.std() for sid,g in df0.groupby('sensor_id')}
CAP=1.6

def design(t,kind):
    cols=[np.ones_like(t)]
    if kind in ('d24','d24+12','d24+trend','d24+12+trend'):
        cols+= [np.sin(W*t),np.cos(W*t)]
    if kind in ('d24+12','d24+12+trend'):
        cols+= [np.sin(2*W*t),np.cos(2*W*t)]
    if kind in ('d24+trend','d24+12+trend','const+trend'):
        cols+= [(t-1440)/1440.0]
    return np.column_stack(cols)

def run(kind, start=0, tmax_rel=None, cap=CAP, grid=np.arange(-200,160,1.0), subs=SUBS, fixed_cap=True):
    out={}
    for sub in subs:
        g=df0[(df0.subsystem==sub)&(df0.tmin>=start)&(df0.tmin<ACT[sub]-1)]
        if tmax_rel is not None: g=g[g.tphys<=1440+tmax_rel[sub]]
        sids=list(g.sensor_id.unique())
        parts={s:g[g.sensor_id==s] for s in sids}
        Xs={s:design(parts[s].tmin.values,kind) for s in sids}
        def prof(t0,slope):
            sse=0.0
            for s in sids:
                h=parts[s]
                ramp=np.minimum(np.clip(h.tphys.values-t0,0,None)*slope,cap)*SGN[s]
                y=h.dev.values-ramp
                b,*_=np.linalg.lstsq(Xs[s],y,rcond=None)
                sse+=((y-Xs[s]@b)**2).sum()/sig[s]**2
            return sse
        vals=[]
        for t0 in grid:
            r=minimize_scalar(lambda s: prof(1440+t0,s),bounds=(0.0005,0.05),method='bounded',options={'xatol':1e-6})
            vals.append((t0,r.x,r.fun))
        v=np.array(vals); i=v[:,2].argmin()
        ok=v[v[:,2]<=v[i,2]+1.0,0]
        out[sub]=(v[i,0],ok.min(),ok.max(),v[i,1]*60,v[i,2]/len(g))
    return out

if __name__=='__main__':
    rows=[]
    cases=[('d24',0,None),('d24+12',0,None),('d24+trend',0,None),('d24+12+trend',0,None),('const+trend',0,None),('const',0,None),
           ('d24',720,None),('d24',1200,None)]
    for kind,start,tm in cases:
        o=run(kind,start,tm)
        rows.append([f'{kind} start={start}']+[f"{o[s][0]:.0f} [{o[s][1]:.0f},{o[s][2]:.0f}]" for s in SUBS])
    print(pd.DataFrame(rows,columns=['variant']+SUBS).to_string())
EOF
cd /app/work && python3 -I variants.py

